/** Public engine types (runtime-design.md §3). Everything in `Data` is plain JSON. */

import type { Stored } from './values.ts';
import type { ChoiceValue, Id, Plan } from './plan.ts';

export type Clock = () => number;
export type Device = 'phone' | 'tablet' | 'desktop';
export type QuestionState = 'not-reached' | 'irrelevant' | 'unanswered' | 'answered';
export type QuotaResult = 'open' | 'full';

export interface StartOptions {
	/** Positive integer, 1 … 2^53 − 1, generated by the server (semantics §7). */
	sessionSeed: number;
	/** Conditions assigned by the server, by assigned-variable id. Missing ones are drawn here. */
	assigned?: Record<Id, ChoiceValue>;
	/** Injected clock (ms). The engine never reads the real time. */
	clock: Clock;
	language?: string;
	device?: Device | null;
	/** URL parameters, for `embedded` variables. Recorded, never trusted for assignment. */
	urlParams?: Record<string, string>;
	sessionId?: string | null;
}

/** A position in the flow: a node list and an index into it. See engine.ts `listFor`. */
export interface Frame {
	k: string;
	i: number;
}

export interface Orders {
	/** Randomiser id → child flow-node ids in realised order (only the picked ones). */
	blocks: Record<Id, Id[]>;
	/** Page id → item ids in realised order (itemOrder: shuffle). */
	items: Record<Id, Id[]>;
	/** Question id → choice codes in realised order (choiceOrder: shuffle). */
	choices: Record<Id, ChoiceValue[]>;
}

export type PageError =
	| { kind: 'required' }
	| { kind: 'range' }
	| { kind: 'constraint' }
	| { kind: 'invalid'; code: string }
	/** From a hook's `rejectPage` (R7). The message is untrusted text: always escaped. */
	| { kind: 'hook'; text: string };

/**
 * A runtime diagnostic, logged, never thrown (semantics.md §3): a type mismatch or a
 * division by zero in an expression, or a malformed URL parameter. `site` names the
 * expression (`items.<id>.showIf`, `pages.<id>.showIf`, `items.<id>.constraint`,
 * `flow.<node>.if`, `quotas.<id>.when`, `variables.<id>.expr`, `variables.<id>`); `path`
 * is a JSON pointer into its AST.
 */
export interface RuntimeDiagnostic {
	code: 'type-mismatch' | 'division-by-zero' | 'embedded.malformed';
	site: string;
	path: string;
}

export interface QuotaEffect {
	kind: 'quota';
	/** The quotaCheck node; the server call is idempotent per (session, node). */
	nodeId: Id;
	quota: Id;
}
export interface EndEffect {
	kind: 'end';
	outcome: Id;
	nodeId: Id | null;
}
/**
 * A researcher hook call (task R7, runtime-design.md §7a): an effect with an invocation id
 * and the state revision it saw. The hook runner (`web/hooks-sandbox`) creates it, runs the
 * hook, and records the validated outcome with `resolve(state, effect, HookResolution)`.
 * A result for any other revision is stale and refused.
 */
export interface HookEffect {
	kind: 'hook';
	invocationId: string;
	event: string;
	revision: number;
}

/** The actions a hook may take, after host-side validation (runtime-design.md §7a). */
export type HookAction =
	| { kind: 'setVariable'; id: Id; value: string | number | boolean | null }
	| { kind: 'addParadata'; key: string; value: string | number | boolean | null }
	| { kind: 'rejectPage'; itemId: Id | null; message: string }
	| { kind: 'setEndRedirect'; templateId: string; params: Record<string, string> }
	| { kind: 'postToParent'; type: string; payload: unknown };

/**
 * A hook outcome as recorded in the event log. `failed`: the hook failed and the session
 * goes on (non-critical, or a flow-critical hook before its retry). `fatal`: a flow-critical
 * hook failed after its retry; the session ends with outcome `hook-failed`.
 */
export interface HookResolution {
	status: 'ok' | 'failed' | 'fatal';
	actions: HookAction[];
	/** The seed of the hook's `ctx.random()` and the injected `ctx.now()`, as used. */
	seed: number;
	now: number;
	error?: string;
	/** Actions the host refused, as short codes (logged, never applied). */
	diagnostics?: string[];
}

export interface HookData {
	vars: Record<Id, string | number | boolean | null>;
	paradata: Array<{ key: string; value: string | number | boolean | null; event: string }>;
	redirect: { templateId: string; params: Record<string, string> } | null;
	/** Parent messages sent (the payloads are in the event log). */
	parentMessages: number;
}

export type Effect = QuotaEffect | EndEffect | HookEffect;

export interface HistoryEntry {
	page: Id;
	cursor: Frame[];
	shownAt: number;
}

export interface Pending {
	effect: QuotaEffect;
	cursor: Frame[];
}

export interface StepResult {
	outcome: 'advanced' | 'invalid' | 'effect' | 'ended';
	to?: Id | null;
	errors?: Record<Id, PageError>;
	effect?: Effect;
}

interface EventBase {
	seq: number;
	t: number;
	rev: number;
	/** Set when the call was refused; the event changed nothing else. */
	rejected?: string;
}
export type EngineEvent =
	| (EventBase & {
			type: 'start';
			sessionSeed: number;
			assigned: Record<Id, ChoiceValue>;
			language: string;
			device: Device | null;
			urlParams: Record<string, string>;
			sessionId: string | null;
	  })
	| (EventBase & { type: 'answer'; item: Id; value: Stored; invalid?: string })
	| (EventBase & { type: 'next'; from: Id | null; result?: StepResult })
	| (EventBase & { type: 'back'; from: Id | null; to?: Id | null })
	| (EventBase & {
			type: 'resolve';
			effect: { kind: string; nodeId?: Id; invocationId?: string; event?: string; revision?: number };
			value: unknown;
			result?: StepResult;
	  })
	| (EventBase & { type: 'language'; language: string })
	/** The participant's answer on the consent page (semantics.md §11). */
	| (EventBase & { type: 'consent'; decision: 'agree' | 'decline'; version: string; result?: StepResult });

/** What the participant decided on the consent page, and when (engine clock). */
export interface ConsentDecision {
	decision: 'agree' | 'decline';
	version: string;
	at: number;
}

export interface Data {
	format: 'osp-engine-state/1';
	planChecksum: string;
	sessionSeed: number;
	sessionId: string | null;
	language: string;
	device: Device | null;
	urlParams: Record<string, string>;
	startedAt: number;
	revision: number;
	/** Stored answers (absent = no value). Kept while hidden until a page submit clears them. */
	values: Record<Id, Stored>;
	/** Questions whose last input could not be read (e.g. "12a" for an integer). */
	invalid: Record<Id, string>;
	/** Pages the flow has reached (shown or skipped as empty). */
	reachedPages: Record<Id, true>;
	/**
	 * Reached pages that a later submit took off the path (semantics.md §3, C3a-6): their
	 * questions are irrelevant and were cleared. Recomputed on every page submit.
	 */
	offPath: Record<Id, true>;
	conditions: Record<Id, ChoiceValue>;
	conditionSource: Record<Id, 'server' | 'seeded'>;
	/** Assigned variables whose `assign` node has been reached (visible to expressions). */
	assignReached: Record<Id, true>;
	orders: Orders;
	/** quotaCheck node id → recorded server result. */
	quotas: Record<Id, QuotaResult>;
	/** Shown pages on the current path; the last one is the current page. */
	history: HistoryEntry[];
	pending: Pending | null;
	errors: Record<Id, PageError>;
	/**
	 * Question states as of the last page change (fixtures/FORMAT.md §4 readings 1 and 8).
	 * Off the current page a state is only re-evaluated when the page changes (next, back,
	 * an effect result), never by an unsubmitted answer or a reload; on the current page
	 * states are live.
	 */
	frozen: Record<Id, QuestionState>;
	ended: { outcome: Id; nodeId: Id | null; at: number } | null;
	/** Runtime diagnostics logged while applying events (de-duplicated, in order). */
	diagnostics: RuntimeDiagnostic[];
	events: EngineEvent[];
	/** What researcher hooks recorded (R7). Absent until the first hook result. */
	hooks?: HookData;
	/** The consent decision (semantics.md §11). Absent until one is made. */
	consent?: ConsentDecision;
}

export interface State {
	readonly plan: Plan;
	readonly clock: Clock;
	readonly data: Data;
}

export interface Snapshot {
	format: 'osp-engine-snapshot/1';
	planChecksum: string;
	revision: number;
	data: Data;
}

/** Text after piping. `value` parts are participant data: HTML-escape them when rendering. */
export type RenderedText = Array<{ kind: 'text'; text: string } | { kind: 'value'; text: string }>;

export interface ViewChoice {
	value: ChoiceValue;
	label: RenderedText;
}

/** One matrix row as shown (semantics.md §2, C2c-1): its own question, value and state. */
export interface ViewRow {
	id: Id;
	label: RenderedText;
	required: boolean;
	state: QuestionState;
	value: Stored;
	error: (PageError & { message: RenderedText | null }) | null;
}

export interface ViewItem {
	id: Id;
	type: string;
	label: RenderedText;
	help: RenderedText | null;
	/** A matrix: true when any row is required. */
	required: boolean;
	/** A matrix: null (each row has its own state). */
	state: QuestionState | null;
	value: Stored;
	/** A matrix: the first row error, in row order (every row error is in `errors`). */
	error: (PageError & { message: RenderedText | null }) | null;
	/** A matrix: its columns. */
	choices: ViewChoice[] | null;
	/** Present for a matrix: its rows in display order. */
	rows?: ViewRow[];
	/** Present for a slider: the track (runtime-design.md §6; starts unanswered). */
	slider?: {
		min: number | string;
		max: number | string;
		step: number | string;
		valueType: 'integer' | 'decimal';
		minLabel: RenderedText | null;
		maxLabel: RenderedText | null;
	};
}

/**
 * How the session ended, resolved for the ending screen (end-of-survey plan §4.1). `message`
 * is the end node's own text, shown above the ending's body. `ending` is the outcome's
 * ending from the plan with its pipes filled, or null when the survey sets none (the app
 * shows its defaults). `status` is the truthful status line the screen must show:
 * `recorded` (a response was kept), `not-recorded` (a consent decline: nothing was kept), or
 * null when the ending hides it (`status: none`; never for a decline).
 */
export interface EndView {
	outcome: Id;
	message: RenderedText | null;
	ending: { title: RenderedText | null; body: RenderedText | null; summary: 'none' | 'answers' } | null;
	status: 'recorded' | 'not-recorded' | null;
}

export interface Position {
	randomiserId: Id;
	index: number;
	of: number;
}

export interface PageView {
	/** `consent`: the consent page is shown (page `$consent`, no items, no nav). */
	status: 'page' | 'pending' | 'ended' | 'consent';
	page: Id | null;
	block: Id | null;
	language: string;
	title: RenderedText;
	items: ViewItem[];
	errors: Record<Id, PageError & { message: RenderedText | null }>;
	nav: { back: boolean; next: boolean } | null;
	/** Where focus goes (runtime-design.md §6): the heading, or the error summary after a failed next. */
	focus: 'heading' | 'error-summary' | null;
	effect: Effect | null;
	end: EndView | null;
	trial: number;
	position: Position | null;
	/** The consent page's texts, while it is shown (semantics.md §11). */
	consent?: { text: RenderedText; agree: RenderedText; decline: RenderedText } | null;
}

export interface AnswerRecord {
	state: QuestionState;
	value: Stored;
}

export interface ResponseRecord {
	format: 'osp-response/1';
	surveyId: Id;
	surveyVersion: number | null;
	planVersion: string;
	planChecksum: string;
	engineVersion: string;
	sessionSeed: number;
	sessionId: string | null;
	language: string;
	device: Device | null;
	end: Id | null;
	endNode: Id | null;
	allocation: 'server' | 'seeded';
	/** Exactly the conditions the server sent at start (osp_runtime.validate_record checks it). */
	assigned: Record<Id, ChoiceValue>;
	/** All conditions in force, including any the engine drew itself. */
	conditions: Record<Id, ChoiceValue>;
	conditionSources: Record<Id, 'server' | 'seeded'>;
	orders: Orders;
	answers: Record<Id, AnswerRecord>;
	csvState: Record<string, QuestionState>;
	embedded: Record<Id, string | number | null>;
	computed: Record<Id, string | boolean | null>;
	/** Export state of each embedded and computed variable (also in `csvState`). */
	variableStates: Record<Id, QuestionState>;
	quotas: Record<Id, QuotaResult>;
	/** Runtime diagnostics the session logged (semantics.md §3). */
	diagnostics: RuntimeDiagnostic[];
	/** Recorded effect results in order (FORMAT.md `response.effects`). */
	effects: Array<{ kind: 'quota'; nodeId: Id; quota: Id; result: QuotaResult }>;
	urlParams: Record<string, string>;
	startedAt: number;
	endedAt: number | null;
	revision: number;
	events: EngineEvent[];
	/** Hook variables, paradata and the chosen end redirect (R7). Present once a hook ran. */
	hooks?: { vars: HookData['vars']; paradata: HookData['paradata']; redirect: HookData['redirect'] };
	/** Surveys with a consent page (semantics.md §11): the version agreed to and when. */
	consentVersion?: string | null;
	consentedAt?: number | null;
}

export interface Ctx {
	trial: number;
	trialId: Id | null;
	blockId: Id | null;
	position: Position | null;
	pagesDone: number;
	pagesEstimated: number;
	conditions: Record<Id, ChoiceValue>;
	language: string;
	device: Device | null;
	elapsedMs: number;
	trialElapsedMs: number;
	results: Record<Id, AnswerRecord>;
	vars: Record<Id, string | number | boolean | null>;
	sessionId: string | null;
}

export class EngineError extends Error {
	constructor(
		readonly code: string,
		message: string
	) {
		super(message);
	}
}
